# -*- coding: utf-8 -*-
"""Portable player: all chapter data embedded; works from file or local HTTP."""
import json
from pathlib import Path
B=Path(__file__).resolve().parent;D=json.loads((B/'timeline.json').read_text())
player=r'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>损失函数 · 我的深度学习之路</title><style>
*{box-sizing:border-box}body{margin:0;background:#FFF7E4;color:#46392F;font-family:"Hiragino Sans GB","PingFang SC",sans-serif}main{max-width:1080px;margin:34px auto;padding:0 28px}header{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:25px}h1{font-size:29px;margin:0 0 9px}p{margin:0;color:#66574A;font-size:14px;line-height:1.7}a{color:#46392F;text-underline-offset:4px}.layout{display:grid;grid-template-columns:minmax(300px,370px) 1fr;gap:42px;align-items:start}.player{background:#FFFCF3;border:2px solid #46392F;border-radius:20px;box-shadow:7px 8px 0 #EDCD74;overflow:hidden}.scrubber{padding:17px 17px 13px;border-bottom:2px solid #D2C7AE}.primary-chapters{display:flex;gap:4px;margin-bottom:9px}.primary-chapters button{position:relative;overflow:hidden;border:1px solid #46392F;border-radius:7px;background:#FFFCF3;height:32px;padding:0;font-size:12px;min-width:0}.primary-chapters .fill{position:absolute;inset:0;background:#EDCD74;transform-origin:left;transform:scaleX(0)}.primary-chapters .label{position:relative}.primary-chapters button[aria-current=true]{outline:2px solid #ED826A;outline-offset:1px}.range-wrap{position:relative}input[type=range]{display:block;width:100%;height:30px;margin:0;accent-color:#ED826A;cursor:ew-resize;touch-action:none}.ticks{display:flex;height:5px;gap:3px;margin:0 1px}.ticks span{background:#D2C7AE;border-radius:2px}.ticks span.done{background:#ED826A}.current{font-size:12px;margin-top:9px;line-height:1.4;min-height:17px}.clock{display:flex;justify-content:space-between;color:#66574A;font-size:12px;margin-top:7px;font-variant-numeric:tabular-nums}video{width:100%;display:block;aspect-ratio:9/16;background:#FFF7E4}.actions{display:flex;gap:8px;padding:13px;flex-wrap:wrap}.actions button,.actions a{border:1px solid #46392F;background:#EDCD74;color:#46392F;font-size:13px;border-radius:8px;padding:8px 13px;text-decoration:none;cursor:pointer}.actions a{background:#FFFCF3}button:focus-visible,input:focus-visible{outline:3px solid #73A6A3;outline-offset:3px}aside h2{font-size:22px;margin:3px 0 10px}aside .hint{margin-bottom:23px}.group-title{font-size:14px;font-weight:600;margin:22px 0 10px;display:flex;justify-content:space-between}.chapters{display:grid;grid-template-columns:1fr 1fr;gap:9px}.chapter{border:1.5px solid #D2C7AE;background:#FFFCF3;color:#46392F;border-radius:11px;padding:12px;text-align:left;cursor:pointer;min-height:75px;line-height:1.55}.chapter:hover{border-color:#46392F}.chapter[aria-current=true]{border:2px solid #46392F;background:#F6E7B4}.chapter small{display:block;color:#66574A;margin-top:3px;font-variant-numeric:tabular-nums}.notes{border-top:1px solid #D2C7AE;margin-top:25px;padding-top:15px;font-size:12px;line-height:1.7;color:#66574A}.error{padding:14px;color:#9D3C28}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}@media(max-width:740px){main{padding:0 17px;margin:22px auto}.layout{grid-template-columns:1fr;gap:27px}.player{max-width:430px;width:100%;margin:auto}header{display:block}header a{display:inline-block;margin-top:12px}h1{font-size:26px}.chapters{grid-template-columns:1fr 1fr}aside{max-width:500px;margin:auto;width:100%}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto}}
.player:fullscreen{max-width:none;width:100vw;height:100dvh;display:flex;flex-direction:column;border:0;border-radius:0;box-shadow:none;overflow:hidden}.player:fullscreen .scrubber{flex:none}.player:fullscreen video{flex:1;min-height:0;aspect-ratio:auto;object-fit:contain}.player:fullscreen .actions{flex:none;justify-content:center}</style></head><body><main><header><div><h1>换把评分尺，模型就换答案</h1><p>我的深度学习之路 · 手绘科普 · 3 分钟看懂损失函数</p></div><div><a href="../../001-introduction.md">阅读知识点文章 ↗</a><br><a href="https://github.com/shikanon/my-deep-learning-journey" target="_blank" rel="noopener">关注 GitHub 项目 ↗</a></div></header><div class="layout"><section class="player" aria-label="视频播放器"><div class="scrubber"><nav class="primary-chapters" aria-label="三部分内容"></nav><label class="sr-only" for="seek">拖动进度，跳转小节</label><div class="range-wrap"><input id="seek" type="range" min="0" value="0" step="0.01" aria-valuetext="开始"><div class="ticks" aria-hidden="true"></div></div><div class="current" id="current">01 · 换把评分尺，模型就换答案</div><div class="clock"><span id="time">00:00 / 03:00</span><span>拖动上方滑块跳转</span></div></div><video id="film" src="renders/loss-functions-v3.mp4" poster="assets/poster.jpg" preload="metadata" controls playsinline></video><div class="actions"><button id="play" type="button">播放</button><a href="renders/loss-functions-v3.mp4" download>下载视频</a><button id="restart" type="button">从头播放</button><button id="fullscreen" type="button">全屏观看</button></div><div id="error" class="error" hidden></div></section><aside><h2>沿着三个问题，看懂损失</h2><p class="hint">先看为什么需要评分，再看评分规则如何演化，最后看看今天的新问题。点击小节可跳转；进度条也支持键盘左右键。</p><div id="chapter-list"></div><div class="notes">顶部滑块与所有章节按钮直接控制视频时间。视频画面中的章节条也会同步显示当前小节。解说文字、原文出处、字幕与制作工程均保留在 video 文件夹。知识主线按 30% / 50% / 20% 安排；最后一个小节为项目引导。</div></aside></div></main><script>
const DATA=__DATA__;
const film=document.getElementById('film'),seek=document.getElementById('seek'),play=document.getElementById('play');
const fmt=t=>{t=Math.max(0,Math.floor(t));return String(Math.floor(t/60)).padStart(2,'0')+':'+String(t%60).padStart(2,'0')};
seek.max=DATA.duration;
DATA.chapters.forEach((c,i)=>{
 const b=document.createElement('button');b.type='button';b.style.flex=c.share;b.setAttribute('aria-label','跳转：'+c.title);b.innerHTML='<span class="fill"></span><span class="label">'+['为什么 30%','演化 50%','前沿 20%'][i]+'</span>';b.onclick=()=>jump(c.start+.02);document.querySelector('.primary-chapters').append(b);
 const title=document.createElement('div');title.className='group-title';title.innerHTML='<span>'+c.title+'</span><span>'+Math.round(c.share*100)+'%</span>';document.getElementById('chapter-list').append(title);
 const grid=document.createElement('div');grid.className='chapters';document.getElementById('chapter-list').append(grid);
 DATA.scenes.filter(s=>s.chapter===c.id).forEach(s=>{const index=DATA.scenes.indexOf(s);const b=document.createElement('button');b.type='button';b.className='chapter';b.dataset.id=s.id;b.setAttribute('aria-label','跳转小节 '+(index+1)+'：'+s.title);b.innerHTML='<span>'+String(index+1).padStart(2,'0')+' · '+s.title+'</span><small>'+fmt(s.start)+' — '+fmt(s.end)+'</small>';b.onclick=()=>jump(s.start+.02);grid.append(b);});
});
DATA.scenes.forEach(s=>{const mark=document.createElement('span');mark.style.flex=s.end-s.start;document.querySelector('.ticks').append(mark);});
function jump(t){film.currentTime=Math.min(Math.max(t,0),DATA.duration);sync();}
function sync(){const t=film.currentTime;seek.value=t;document.getElementById('time').textContent=fmt(t)+' / '+fmt(film.duration||DATA.duration);const index=DATA.scenes.reduce((last,s,i)=>t+.0001>=s.start?i:last,0);const s=DATA.scenes[index];document.getElementById('current').textContent=String(index+1).padStart(2,'0')+' · '+s.title;seek.setAttribute('aria-valuetext',fmt(t)+'，'+s.title);
 document.querySelectorAll('.chapter').forEach(b=>b.setAttribute('aria-current',b.dataset.id===s.id?'true':'false'));
 document.querySelectorAll('.primary-chapters button').forEach((b,i)=>{const c=DATA.chapters[i];b.setAttribute('aria-current',s.chapter===c.id?'true':'false');b.querySelector('.fill').style.transform='scaleX('+Math.min(1,Math.max(0,(t-c.start)/(c.end-c.start)))+')';});
 document.querySelectorAll('.ticks span').forEach((m,i)=>m.classList.toggle('done',i<=index));play.textContent=film.paused?'播放':'暂停';
}
seek.addEventListener('input',()=>jump(Number(seek.value)));film.addEventListener('timeupdate',sync);film.addEventListener('seeked',sync);film.addEventListener('loadedmetadata',sync);film.addEventListener('play',sync);film.addEventListener('pause',sync);film.addEventListener('ended',sync);
play.onclick=()=>film.paused?film.play():film.pause();document.getElementById('restart').onclick=()=>{jump(0);film.play()};
document.getElementById('fullscreen').onclick=()=>document.fullscreenElement?document.exitFullscreen():document.querySelector('.player').requestFullscreen();document.addEventListener('fullscreenchange',()=>{document.getElementById('fullscreen').textContent=document.fullscreenElement?'退出全屏':'全屏观看'});
film.addEventListener('error',()=>{const e=document.getElementById('error');e.hidden=false;e.textContent='未找到视频。请把成片放在 renders/loss-functions-v3.mp4 后重新打开本页。'});sync();
</script></body></html>'''
player=player.replace('__DATA__',json.dumps({k:D[k] for k in ['duration','chapters','scenes']},ensure_ascii=False,separators=(',',':')))
(B/'watch.html').write_text(player)
print('Interactive player saved')
